/*~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
~~ _progress-indicator.scss
~~
~~ This file contains the styles for styling the Progress Indicator
~~
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~*/
.progress-container {
  display: flex;
  margin: 0;
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: rgba(255, 255, 255, 0.9);
  align-items: center;
  justify-content: center;
  transition: visibility 0ms ease 300ms, opacity 300ms ease;
  visibility: hidden;
  opacity: 0;
}
.progress-container.show-progress {
  visibility: visible;
  opacity: 1;
  transition-delay: 0ms;
  transition-duration: 300ms;
  transition-timing-function: linear;
}
.progress-container .progress-body {
  background-image: url("images/cap-loader.gif");
  background-size: 100% 100%;
  height: 5rem;
  margin: 0 auto 0.5rem;
  width: 5rem;
  position: relative;
}
.progress-container .progress-text {
  color: #3c1053;
  text-align: center;
}
.progress-container .progress-text:after {
  content: "";
  animation-name: loading-text;
  animation-duration: 5s;
  animation-iteration-count: infinite;
}

@keyframes loading-text {
  25% {
    content: ".";
  }
  50% {
    content: "..";
  }
  75%, 100% {
    content: "...";
  }
}
