.dc-carousel {
  display: block;
}
.dc-carousel__scroller {
  width: 100%;
  position: relative;
}
.dc-carousel.is-animating .carousel-scroller {
  overflow: hidden;
}
.dc-carousel__page {
  display: none;
  position: relative;
  transition: 300ms ease all;
  padding: 0;
  width: 100%;
}
.dc-carousel__page--active, .dc-carousel__page--prev, .dc-carousel__page--next {
  display: flex;
}
.dc-carousel__page--next, .dc-carousel__page--prev {
  position: absolute;
  top: 0;
}
.dc-carousel__page--left {
  transform: translateX(-100%);
}
.dc-carousel__page--next.dc-carousel__page--left, .dc-carousel__page--prev.dc-carousel__page--right {
  transform: translateX(0);
}
.dc-carousel__page--next {
  transform: translateX(100%);
}
.dc-carousel__page--right {
  transform: translateX(100%);
}
.dc-carousel__page--prev {
  transform: translateX(-100%);
}

@media print, screen and (min-width: 0px) {
  .dc-carousel.all-hide {
    display: none;
  }
  .dc-carousel.all-show {
    display: block;
  }
