  .dc-carousel.medium-hide {
    display: none;
  }
  .dc-carousel.medium-show {
    display: block;
  }
}
@media print, screen and (min-width: 1200px) {
  .dc-carousel.large-hide {
    display: none;
  }
  .dc-carousel.large-show {
    display: block;
  }
}
