  display: block !important;
  height: 1px;
  left: -9999px !important;
  overflow: hidden;
  position: absolute !important;
  width: 1px;
}

.spotlight {
  display: block;
  margin-right: 1rem;
}
.spotlight__container {
  z-index: 1;
  width: 100%;
  display: block;
  overflow: hidden;
  height: 100%;
  animation: sljunk 0.01s;
  margin-bottom: 0.5rem;
  border: 1px solid;
}
.spotlight__controls {
  text-align: right;
}
.spotlight__wrapper {
  position: relative;
  display: inline-block;
  transform-origin: top left;
}
.spotlight__image {
  transform: scale(1);
  transform-origin: top left;
  min-width: none !important;
  max-width: none !important;
}
.spotlight__info {
  font-family: monospace;
}
.spotlight__highlighter {
  position: absolute;
  background-color: purple;
  opacity: 0.5;
  left: 0;
  top: 0;
  transform-origin: top left;
}

@keyframes sljunk {
  from {
    width: 100%;
    visibility: hidden;
  }
  to {
    width: 100%;
    visibility: visible;
  }
}
.dc-managed-content {
  width: 100% !important;
}
.dc-managed-content iframe {
  height: 500px;
}

